def main():
    os.umask(0o077)
    key = os.environ.pop("PAPER3_FOLLOWUP_DOWNLOAD_KEY", "")
    cache = Path(os.environ.get("PAPER3_FOLLOWUP_DOWNLOAD_CACHE", str(Path.home() / "paper3-followup-downloads")))
    cache.mkdir(parents=True, exist_ok=True)
    installer = cache / (INSTALLER_SHA256 + ".py")
    if not installer.is_file() or hashlib.sha256(installer.read_bytes()).hexdigest() != INSTALLER_SHA256:
        if len(key) != 64 or any(c not in "0123456789abcdefABCDEF" for c in key):
            raise SystemExit("Use the complete launch command supplied with this package")
        try:
            result = subprocess.run(["openssl", "enc", "-d", "-aes-256-ctr", "-K", key, "-iv", IV],
                                    input=base64.b85decode(CIPHERTEXT_B85), capture_output=True, timeout=30)
        except (OSError, subprocess.TimeoutExpired):
            raise SystemExit("Cannot unpack installer: openssl is missing or did not finish") from None
        if result.returncode or hashlib.sha256(result.stdout).hexdigest() != INSTALLER_SHA256:
            raise SystemExit("Package/key mismatch; download the matching launch command")
        fd, temporary = tempfile.mkstemp(prefix=".installer-", dir=cache)
        try:
            with os.fdopen(fd, "wb") as stream:
                stream.write(result.stdout)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temporary, installer)
        finally:
            if os.path.exists(temporary):
                os.unlink(temporary)
    installer.chmod(0o600)
    print("ONLINE_PACKAGE_VERIFIED " + INSTALLER_SHA256, flush=True)
    return subprocess.call([sys.executable, "-I", "-S", "-B", "-u", str(installer), *sys.argv[1:]])

if __name__ == "__main__":
    raise SystemExit(main())
